import React, { useState, useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import { iaAPI } from '../services/api';
import ReactMarkdown from 'react-markdown';

const ChatPage = ({ asignaciones }) => {
  const { grado, division, materiaId } = useParams();
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef(null);

  // Encontrar la asignación actual
  const asignacionActual = asignaciones.find(
    a => a.grado === grado && a.division === division && a.materia_id === parseInt(materiaId)
  );

  // Cargar alumnos del localStorage
  const getAlumnos = () => {
    const key = `alumnos_${grado}_${division}`;
    const stored = localStorage.getItem(key);
    if (stored) {
      const alumnos = JSON.parse(stored);
      return alumnos.map(a => ({
        nombre: a.nombre,
        apellido: a.apellido,
        nivel: a.niveles?.[materiaId] || 'LE',
        observaciones: a.observaciones || '',
      }));
    }
    return [];
  };

  // Scroll al último mensaje
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Mensaje de bienvenida
  useEffect(() => {
    if (asignacionActual && messages.length === 0) {
      const alumnos = getAlumnos();
      const neet = alumnos.filter(a => a.nivel === 'NEE').length;
      const lp = alumnos.filter(a => a.nivel === 'LP').length;
      const le = alumnos.filter(a => a.nivel === 'LE').length;

      setMessages([{
        role: 'assistant',
        content: `¡Hola! Soy tu asistente de planificación para **${grado}° ${division} - ${asignacionActual.materia_nombre}**.

${alumnos.length > 0 
  ? `Tenés ${alumnos.length} alumnos cargados: ${neet} NEE, ${lp} LP y ${le} LE.`
  : 'Todavía no cargaste alumnos. Te recomiendo hacerlo para que pueda personalizar mejor las planificaciones.'}

¿En qué puedo ayudarte? Podés pedirme:
- **Planificaciones** diferenciadas por nivel
- **Actividades** adaptadas para cada grupo
- **Consultas** sobre la currícula
- **Adaptaciones** de contenidos existentes`,
      }]);
    }
  }, [asignacionActual]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMessage }]);
    setIsLoading(true);

    try {
      const alumnos = getAlumnos();
      const response = await iaAPI.consultar(
        userMessage,
        grado,
        division,
        asignacionActual?.materia_nombre || '',
        alumnos
      );

      if (response.success) {
        setMessages(prev => [...prev, {
          role: 'assistant',
          content: response.respuesta,
          tipo: response.tipo_consulta,
          contexto: response.contexto_utilizado,
        }]);
      } else {
        throw new Error(response.error || 'Error al procesar la consulta');
      }
    } catch (error) {
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: `Lo siento, ocurrió un error: ${error.message}. Por favor, intentá de nuevo.`,
        isError: true,
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  // Sugerencias rápidas
  const sugerencias = [
    'Necesito una planificación para trabajar fracciones',
    '¿Qué contenidos debo dar este mes?',
    'Dame actividades diferenciadas para mi clase',
    '¿Cómo adapto esta actividad para alumnos NEE?',
  ];

  const handleSugerencia = (texto) => {
    setInput(texto);
  };

  if (!asignacionActual) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-500">Asignación no encontrada</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-8rem)]">
      {/* Header */}
      <div className="bg-white border-b border-gray-200 px-4 py-3 flex items-center justify-between">
        <div>
          <h1 className="text-lg font-semibold text-gray-900">
            Asistente IA - {grado}° {division}
          </h1>
          <p className="text-sm text-gray-500">{asignacionActual.materia_nombre}</p>
        </div>
        <div className="flex items-center text-sm text-gray-500">
          <span className="w-2 h-2 bg-green-500 rounded-full mr-2"></span>
          Conectado
        </div>
      </div>

      {/* Mensajes */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50">
        {messages.map((message, index) => (
          <div
            key={index}
            className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-3xl rounded-2xl px-4 py-3 ${
                message.role === 'user'
                  ? 'bg-indigo-600 text-white'
                  : message.isError
                  ? 'bg-red-50 border border-red-200 text-red-800'
                  : 'bg-white border border-gray-200 text-gray-800'
              }`}
            >
              {message.role === 'assistant' ? (
                <div className="prose prose-sm max-w-none">
                  <ReactMarkdown
                    components={{
                      table: ({node, ...props}) => (
                        <div className="overflow-x-auto my-4">
                          <table className="min-w-full border-collapse border border-gray-300" {...props} />
                        </div>
                      ),
                      th: ({node, ...props}) => (
                        <th className="border border-gray-300 bg-gray-100 px-3 py-2 text-left text-sm font-medium" {...props} />
                      ),
                      td: ({node, ...props}) => (
                        <td className="border border-gray-300 px-3 py-2 text-sm" {...props} />
                      ),
                      h3: ({node, ...props}) => (
                        <h3 className="text-lg font-semibold text-gray-900 mt-6 mb-3" {...props} />
                      ),
                      strong: ({node, ...props}) => (
                        <strong className="font-semibold text-gray-900" {...props} />
                      ),
                      ul: ({node, ...props}) => (
                        <ul className="list-disc list-inside space-y-1 my-2" {...props} />
                      ),
                      ol: ({node, ...props}) => (
                        <ol className="list-decimal list-inside space-y-1 my-2" {...props} />
                      ),
                    }}
                  >
                    {message.content}
                  </ReactMarkdown>
                </div>
              ) : (
                <p>{message.content}</p>
              )}

              {/* Contexto usado */}
              {message.contexto && message.contexto.length > 0 && (
                <div className="mt-3 pt-3 border-t border-gray-200">
                  <p className="text-xs text-gray-500 mb-1">Fuentes consultadas:</p>
                  <div className="flex flex-wrap gap-1">
                    {message.contexto.map((ctx, i) => (
                      <span key={i} className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded">
                        {ctx.fuente}
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}

        {/* Loading indicator */}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white border border-gray-200 rounded-2xl px-4 py-3">
              <div className="flex items-center space-x-2">
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Sugerencias */}
      {messages.length <= 1 && (
        <div className="px-4 py-2 bg-gray-50 border-t border-gray-200">
          <p className="text-xs text-gray-500 mb-2">Sugerencias:</p>
          <div className="flex flex-wrap gap-2">
            {sugerencias.map((sug, i) => (
              <button
                key={i}
                onClick={() => handleSugerencia(sug)}
                className="text-sm px-3 py-1.5 bg-white border border-gray-200 rounded-full hover:bg-gray-50 text-gray-700"
              >
                {sug}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Input */}
      <form onSubmit={handleSubmit} className="bg-white border-t border-gray-200 p-4">
        <div className="flex items-center gap-3">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Escribí tu consulta..."
            disabled={isLoading}
            className="flex-1 px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-gray-50"
          />
          <button
            type="submit"
            disabled={isLoading || !input.trim()}
            className="px-6 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </form>
    </div>
  );
};

export default ChatPage;
